  | { readonly kind: typeof SELECTION_KINDS.one; readonly index: number }
  | { readonly kind: typeof SELECTION_KINDS.mismatch; readonly first: number;
      readonly second: number; readonly remainingMs: number };

export interface GameState {
  readonly board: BoardDescription;
  readonly deck: readonly number[];
  readonly matched: readonly number[];
  readonly selection: Selection;
  readonly moves: number;
  readonly elapsedMs: number;
