  for (const index of candidates) {
    if (!nonnegativeInteger(index, deck.length - 1) || matched.includes(index)) return null;
    const face = deck[index];
    if (face === undefined) return null;
    faces.set(face, (faces.get(face) ?? 0) + 1);
    matched.push(index);
