    case 'one': return exactKeys(value, ['kind', 'index']) && eligible(value.index)
      ? { kind: 'one', index: value.index } : null;
    case 'mismatch': {
      if (!exactKeys(value, ['kind', 'first', 'second', 'remainingMs']) ||
