import { useEffect } from 'react';

export function useActiveClock(
  epoch: number,
  onTime: (now: number, epoch: number) => void,
  onVisibility: (visible: boolean, epoch: number) => void,
): void {
  useEffect(() => {
    let cancelled = false;
    let frame = 0;
    const tick = (now: number): void => {
      if (cancelled) return;
      onTime(now, epoch);
      frame = requestAnimationFrame(tick);
    };
    const visibility = (): void => {
      onTime(performance.now(), epoch);
      onVisibility(!document.hidden, epoch);
    };
    frame = requestAnimationFrame(tick);
    document.addEventListener('visibilitychange', visibility);
    return () => {
      cancelled = true;
      cancelAnimationFrame(frame);
      document.removeEventListener('visibilitychange', visibility);
    };
  }, [epoch, onTime, onVisibility]);
}
import { MAX_SEED } from '../boardCode.ts';
import type { Size } from '../boardCode.ts';
import { createGame } from '../state.ts';
import type { GameState } from '../state.ts';

export function freshGame(size: Size, previousSeed?: number): GameState {
  const bytes = new Uint32Array(1);
  crypto.getRandomValues(bytes);
  const random = bytes[0];
  if (random === undefined) throw new Error('Unable to create a deal.');
  let seed = random % MAX_SEED + 1;
  if (seed === previousSeed) seed = seed % MAX_SEED + 1;
  const game = createGame(`np1-${size}-${seed}`);
  if (!game) throw new Error('Unable to create a deal.');
  return game;
}
import { isWon, pairCount } from '../state.ts';
import type { GameState } from '../state.ts';
import { formatTime } from '../transitions.ts';

export interface Announcement { readonly id: number; readonly text: string }

export function turnAnnouncement(game: GameState): string {
  if (game.selection.kind === 'mismatch') return 'No match. Cards close after a short pause.';
  if (isWon(game)) return `Pair found. All pairs found in ${game.moves} moves and ${formatTime(game.elapsedMs)}.`;
  const pairs = pairCount(game);
  return `Pair found. ${pairs} ${pairs === 1 ? 'pair' : 'pairs'} matched.`;
}

